function regimeFromText(text) {
  const t = String(text || '').toLowerCase();
  if (/cours du soir|\ben soir\b|\bsoir\b/.test(t)) return 'soir';
  if (/alternan/.test(t)) return 'alternance';
  if (/cours du jour|\bdu jour\b/.test(t)) return 'jour';
